import numpy as npimport sysimport Video# Called with 2 arguments# -- kind of approximation:# L Left Riemann Sum# R Right Riemann Sum# M Middle Riemann Sum# T Trapesoidal Riemann Sum# S Simpson Rule# -- What to integrate# P Parabola# N Normal# L 1/x# S Sine function# Z ZiggZagif len(sys.argv) != 3:    print("\n*** Required arguments: kind of approximation, function to integrate")    exit()    kind = sys.argv[1]what = sys.argv[2]    # for each integral provide# - function,# - lb lower bound of integration    class ZigZag:    def __init__(self):        self.lb = -10        self.ub =  10        self.xmin = -12        self.xmax =  11        self.ymin = -1        self.ymax =  2        self.K2 = None         # no second derivative        self.K4 = None         # no fourth derivative                    def func(self, x):        i = np.floor(x)        if i % 2 == 0: return np.abs(i - x)        else:          return np.abs(i+1 - x)                class Custom:    def __init__(self):        self.lb = 0        self.ub = np.pi/2        self.xmin = self.lb        self.xmax = self.ub        self.ymin = 0        self.ymax = 1        self.K2 = None         self.K4 = None                    def func(self, x):        return 10*((np.sin(x/4))**2) * np.exp(-x**2)        class Sine:    def __init__(self):        self.lb = -np.pi        self.ub =  np.pi        self.xmin = -5        self.xmax =  4        self.ymin = -2        self.ymax =  2        self.K2 = 1  # second derivative bounded by 1        self.K4 = 1  # fourth derivative bounded by 1                            def func(self, x):        return np.sin(x) + 0.    class Parabola:    def __init__(self):        self.lb = -5        self.ub =  5        self.xmin = -9        self.xmax =  6        self.ymin = -1        self.ymax = 36        self.K2 = 2  # second derivative == 2        self.K4 = 0  # fourth derivative == 0            def func(self, x):        return x**2 + 1    class Log:    def __init__(self):        self.lb = 1        self.ub = 3        self.xmin = -2        self.xmax =  6        self.ymin = -2        self.ymax =  5        self.K2 = 2   # second derivative at its maximum x = 1        self.K4 = 24  # fourth derivative at its maximum x = 1            def func(self, x):        if x == 0:            return None        else:            return 1/x        class Normal:    def __init__(self):        self.lb = -1        self.ub =  1.5        self.xmin = -2        self.xmax =  2        self.ymin = -0.05        self.ymax =  0.5        K2minx = np.sqrt(0.5)        self.K2 = self.func(K2minx)*(2*K2minx)  # maximum of second derivative        print(K2minx, self.K2)        self.K4 = self.K2                     # I am too lazy to calculate that            def func(self, x):        return np.exp(-x**2)/np.sqrt(2*np.pi)    class NumericalIntegration:    def __init__(self, integral, video):  # Uses video to display approximation        self.integral = integral        self.video = video        self.xrange = self.integral.xmax - self.integral.xmin        self.yrange = self.integral.ymax - self.integral.ymin                self.x_text_margin = self.integral.xmin + 0.01*self.xrange        self.y_text_margin = self.integral.ymax - 0.01*self.yrange        self.y_text_size   = self.yrange*0.03    def area_color(self, y):        if y >= 0: return (  0, 255, 255)  # cyan for positive area        else:      return (  0, 200, 200)  # else for negative area            def draw_axes(self):        video.line((self.integral.xmin, 0), (self.integral.xmax, 0), 'black', 2)        video.line((0, self.integral.ymin), (0, self.integral.ymax), 'black', 2)                    def draw_func(self, n):        h = self.xrange/n        for i in range(n):            x0 = self.integral.xmin + h*i            x1 = self.integral.xmin + h*(i+1)                        video.line((x0, self.integral.func(x0)), (x1, self.integral.func(x1)), 'red', width = 2)                    def draw_area_under_func(self):        n = 1000        h = (self.integral.ub - self.integral.lb)/n        for i in range(n):            x = self.integral.lb + h*i            y = self.integral.func(x)            video.line((x, 0), (x, y), self.area_color(y), width = 2)                def draw_bounds(self):        video.line((self.integral.lb, 0),                   (self.integral.ub, 0), 'magenta', width = 5)        video.line((self.integral.lb, 0),                   (self.integral.lb, self.integral.func(self.integral.lb)), 'magenta', width = 5)        video.line((self.integral.ub, 0),                   (self.integral.ub, self.integral.func(self.integral.ub)), 'magenta', width = 5)            def errorBound(self, kind, n):        r = self.integral.ub - self.integral.lb    # size of integration inverval                K2 = self.integral.K2        K4 = self.integral.K4        if K4 == None: return None       # assume that both second and fourth derivative exists or neither                match(kind):            case 'L' : return None   # no bound for Left Riemann            case 'R' : return None   # no bound for Right Riemann            case 'M' : return K2*(r**3)/( 24*(n**2))            case 'T' : return K2*(r**3)/( 12*(n**2))            case 'S' : return K4*(r**5)/(180*(n**4))                                                    def draw_riemann(self, start, end, n, kind):        h = (self.integral.ub - self.integral.lb)/n        area = 0        for i in range(n):            x0 = self.integral.lb + h*i            x1 = self.integral.lb + h*(i+1)            match(kind):                case 'L': y0 = y1 = self.integral.func(x0);                         k = "Left"                case 'R': y0 = y1 = self.integral.func(x1);                         k = "Right"                case 'M': y0 = y1 = self.integral.func((x0+x1)/2);                  k = "Middle"                case 'T': y0 = self.integral.func(x0); y1 = self.integral.func(x1); k = "Trapezoidal"            new_area = h*(y0+y1)/2            area = area + new_area                        video.polygon([(x0, 0),                           (x1, 0),                           (x1, y1),                           (x0, y0)],                          self.area_color(new_area),  width = 0)            video.polygon([(x0, 0),                           (x1, 0),                           (x1, y1),                           (x0, y0)],                          'black',  width = 1)        self.draw_text(kind, area, n)                                                        def draw_simpson(self, start, end, n):        h = (self.integral.ub - self.integral.lb)/n        area = 0        for i in range(n):            x0 = self.integral.lb + h*i            x1 = self.integral.lb + h*(i+0.5)            x2 = self.integral.lb + h*(i+1)            y0 = self.integral.func(x0);            y1 = self.integral.func(x1);            y2 = self.integral.func(x2);               new_area = h*(y0 + 4*y1 + y2)/6            area = area + new_area            k = 100            poly = [(x0 + h*j/k, self.s(x0 + h*j/k, h/2, x0, y0, y1, y2))  for j in range(k+1)]            poly.append((x2, 0))            poly.append((x0, 0))                                                        video.polygon(poly, self.area_color(new_area),  width = 0)            video.polygon(poly, 'black',                    width = 1)        self.draw_text('S', area, n)                                                           # Calculation of the Simpson's parabola to approximate the function    def s(self,          x,              r,             # h/2          x0,            # start of interval          y0, y1, y2):   # the three y values        # calculate the coefficients a, b, c        a = (y0 - 2*y1 + y2)/(2*r*r)        b = (y1 - y0)/r - 2*a*x0 - a*r        c = y0 - a*x0*x0 - b*x0        return a*x*x + b*x + c    def draw_text(self, kind, area, n):        xm = self.x_text_margin        ym = self.y_text_margin        ts = self.y_text_size        match kind:            case 'R': s = "Right Riemann"            case 'L': s = "Left Riemann"            case 'M': s = "Middle Riemann"                        case 'T': s = "Trepesoidal"            case 'S': s = "Simpson's"                    video.text("%s Approximation" % s,    (xm, ym - 0*ts), 'black')        video.text("Num intervals:%4d intervals" % n,      (xm, ym - 1*ts), 'black')        video.text("Area:         %15.10f" % area,   (xm, ym - 2*ts), 'black')        e = self.errorBound(kind, n)        if e != None:            video.text("|Error| <=    %15.10f" % e,(xm, ym - 3*ts), 'black')                # This is invoked by video at given to to generate a new image    def run(self, time, mouseClick, mousePos):                if time == 0:                    # initially just draw the area to be integrated            self.draw_area_under_func()        else:            if kind == 'S':                self.draw_simpson(self.integral.lb, self.integral.ub, 2+int(time))            else:                self.draw_riemann(self.integral.lb, self.integral.ub, 2+int(time), kind)                                self.draw_axes()        self.draw_func(1000)        self.draw_bounds()        # mainmatch (what):    case 'P': integral = Parabola()    case 'N': integral = Normal()    case 'L': integral = Log()            case 'S': integral = Sine()    case 'Z': integral = ZigZag()    case 'C': integral = Custom()            # initialize the video with the integral's dimensionsvideo = Video.Video(1, integral.xmin, integral.xmax, integral.ymin, integral.ymax)# Initialize the NumericalIntegrationni = NumericalIntegration(integral, video)# run the video using ni to fill screenvideo.video(ni)    